-- Scholarly articles v2: Form 10 follows the target criteria; category-based ideas, eight suggestions, shortlist of four.
update public.tasks set data = data || '{"deps":["targets"]}'::jsonb where data->>'key' = 'f10' and coalesce(data->>'status','') not in ('Done','Skipped');
update public.tasks set data = data || jsonb_build_object('detail', $q$Optional: 3 to 6 article ideas in your own words, grouped by category, with example ideas for your field. We add ours and pick the best four together.$q$) where data->>'key' = 'f10';
update public.tasks set data = data || jsonb_build_object('detail', $q$Eight article ideas across categories, each with an abstract, venue tier and possible journals; memberships to pursue, and how many and what kind of judging roles. Names are unverified until you check them.$q$) where data->>'key' = 'recs';
update public.tasks set data = data || jsonb_build_object('detail', $q$Compare with the candidate's own ideas, shortlist the best four articles, then add, edit or remove any suggestion in the Plan tab. Approving turns the shortlist into tasks, held back until you have reviewed the plan with the candidate.$q$) where data->>'key' = 'plan';
